import{_ as h,C as r,o as e,c as B,a2 as i,b as E,w as s,a as o,E as l,a3 as d}from"./chunks/framework.CAKCj7G0.js";const D=JSON.parse('{"title":"Redis GEO 数据类型","description":"","frontmatter":{},"headers":[],"relativePath":"数据库/Redis/数据类型/geo.md","filePath":"数据库/Redis/数据类型/geo.md","lastUpdated":1768053784000}'),n={name:"数据库/Redis/数据类型/geo.md"};function A(p,a,C,F,c,k){const t=r("Mermaid");return e(),B("div",null,[a[4]||(a[4]=i(`<h1 id="redis-geo-数据类型" tabindex="-1">Redis GEO 数据类型 <a class="header-anchor" href="#redis-geo-数据类型" aria-label="Permalink to &quot;Redis GEO 数据类型&quot;">​</a></h1><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><p>Redis GEO 是 Redis 专门用于处理地理位置相关数据的功能，它并非全新的底层数据结构，而是基于 <strong>Sorted Set（有序集合）</strong> 实现的地理位置功能，通过将经纬度编码成有序集合的 <code>score</code>（使用 Geohash 算法），实现地理位置的存储、距离计算、范围查找等操作。</p><h3 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h3><ul><li>支持存储经纬度坐标，并关联一个唯一的成员（如商家ID、用户ID）</li><li>支持计算两个位置之间的距离</li><li>支持根据指定位置查找指定范围内的其他位置（附近的人/商家）</li><li>底层依赖有序集合，因此能复用有序集合的部分命令（如 <code>ZREM</code> 删除位置）</li></ul><hr><h2 id="核心命令" tabindex="-1">核心命令 <a class="header-anchor" href="#核心命令" aria-label="Permalink to &quot;核心命令&quot;">​</a></h2><p>Redis GEO 提供了六个核心命令，用于地理位置的存储、查询和计算。</p><h3 id="geoadd-添加地理位置" tabindex="-1">GEOADD 添加地理位置 <a class="header-anchor" href="#geoadd-添加地理位置" aria-label="Permalink to &quot;GEOADD 添加地理位置&quot;">​</a></h3><p>将一个或多个经纬度-成员对添加到指定的 GEO 键中。</p><p><strong>语法</strong>：<code>GEOADD key 经度 纬度 成员 [经度 纬度 成员 ...]</code></p><p><strong>示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 添加3个商家的位置：美团总部、饿了么总部、京东物流总部</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GEOADD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restaurant:location</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 116.39748</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 39.90882</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;meituan&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 121.47370</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 31.23042</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;eleme&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 116.60680</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 39.91758</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;jdlogistics&quot;</span></span></code></pre></div><p><strong>返回值</strong>：成功添加的成员数量（整数）</p><h3 id="geopos-获取成员经纬度" tabindex="-1">GEOPOS 获取成员经纬度 <a class="header-anchor" href="#geopos-获取成员经纬度" aria-label="Permalink to &quot;GEOPOS 获取成员经纬度&quot;">​</a></h3><p>根据成员名称查询其对应的经纬度坐标。</p><p><strong>语法</strong>：<code>GEOPOS key 成员 [成员 ...]</code></p><p><strong>示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查询美团和饿了么的经纬度</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GEOPOS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restaurant:location</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;meituan&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;eleme&quot;</span></span></code></pre></div><p><strong>返回值</strong>：数组形式，每个元素对应一个成员的经纬度 <code>[经度, 纬度]</code>，不存在的成员返回 nil</p><h3 id="geodist-计算距离" tabindex="-1">GEODIST 计算距离 <a class="header-anchor" href="#geodist-计算距离" aria-label="Permalink to &quot;GEODIST 计算距离&quot;">​</a></h3><p>计算两个地理位置之间的直线距离，支持指定单位。</p><p><strong>语法</strong>：<code>GEODIST key 成员1 成员2 [单位]</code></p><p><strong>单位可选</strong>：<code>m</code>（米，默认）、<code>km</code>（千米）、<code>mi</code>（英里）、<code>ft</code>（英尺）</p><p><strong>示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 计算美团和京东物流总部之间的距离（单位：千米）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GEODIST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restaurant:location</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;meituan&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;jdlogistics&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> km</span></span></code></pre></div><p><strong>返回值</strong>：距离数值（浮点数），如 <code>9.2345</code></p><h3 id="georadius-根据经纬度范围查找" tabindex="-1">GEORADIUS 根据经纬度范围查找 <a class="header-anchor" href="#georadius-根据经纬度范围查找" aria-label="Permalink to &quot;GEORADIUS 根据经纬度范围查找&quot;">​</a></h3><p>以指定经纬度为中心，查找指定半径范围内的所有成员。</p><p><strong>语法</strong>：<code>GEORADIUS key 经度 纬度 半径 单位 [WITHCOORD] [WITHDIST] [ASC|DESC] [COUNT 数量]</code></p><p><strong>参数说明</strong>：</p><ul><li><code>WITHCOORD</code>：返回成员的经纬度</li><li><code>WITHDIST</code>：返回成员与中心的距离</li><li><code>ASC|DESC</code>：按距离升序/降序排列</li><li><code>COUNT</code>：限制返回的成员数量</li></ul><p><strong>示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 以美团总部（116.39748, 39.90882）为中心，查找10千米内的商家，返回距离和经纬度，最多2个</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GEORADIUS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restaurant:location</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 116.39748</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 39.90882</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> km</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WITHDIST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WITHCOORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> COUNT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ASC</span></span></code></pre></div><p><strong>返回值</strong>：数组形式，每个元素包含成员名、距离、经纬度</p><h3 id="georadiusbymember-根据成员范围查找" tabindex="-1">GEORADIUSBYMEMBER 根据成员范围查找 <a class="header-anchor" href="#georadiusbymember-根据成员范围查找" aria-label="Permalink to &quot;GEORADIUSBYMEMBER 根据成员范围查找&quot;">​</a></h3><p>以指定成员的位置为中心，查找指定半径范围内的所有成员（是 <code>GEORADIUS</code> 的简化版）。</p><p><strong>语法</strong>：<code>GEORADIUSBYMEMBER key 成员 半径 单位 [WITHCOORD] [WITHDIST] [ASC|DESC] [COUNT 数量]</code></p><p><strong>示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 以美团总部为中心，查找10千米内的商家</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GEORADIUSBYMEMBER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restaurant:location</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;meituan&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> km</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WITHDIST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ASC</span></span></code></pre></div><h3 id="geohash-获取-geohash-编码" tabindex="-1">GEOHASH 获取 Geohash 编码 <a class="header-anchor" href="#geohash-获取-geohash-编码" aria-label="Permalink to &quot;GEOHASH 获取 Geohash 编码&quot;">​</a></h3><p>返回成员对应的 Geohash 字符串。</p><p><strong>语法</strong>：<code>GEOHASH key 成员 [成员 ...]</code></p><p><strong>示例</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GEOHASH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restaurant:location</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;meituan&quot;</span></span></code></pre></div><p><strong>返回值</strong>：Geohash 字符串，如 <code>wx4g0s83q90</code></p>`,46)),(e(),E(d,null,{default:s(()=>[l(t,{id:"mermaid-162",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E6%89%A7%E8%A1%8C%20GEOADD%20key%20%E7%BB%8F%E5%BA%A6%20%E7%BA%AC%E5%BA%A6%20%E6%88%90%E5%91%98%22%5D%20--%3E%20B%5B%22%E6%A0%A1%E9%AA%8C%E7%BB%8F%E7%BA%AC%E5%BA%A6%E5%90%88%E6%B3%95%E6%80%A7%22%5D%0A%20%20%20%20B%20--%3E%7C%E4%B8%8D%E5%90%88%E6%B3%95%7C%20Z%5B%22%E8%BF%94%E5%9B%9E%E9%94%99%E8%AF%AF%22%5D%0A%20%20%20%20B%20--%3E%7C%E5%90%88%E6%B3%95%7C%20C%5B%22%E7%BB%8F%E7%BA%AC%E5%BA%A6%20%E2%86%92%20Geohash%2064%E4%BD%8D%E6%95%B4%E6%95%B0score%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E5%B0%86%E6%88%90%E5%91%98%E4%BD%9C%E4%B8%BAmember%3Cbr%2F%3Escore%E4%BD%9C%E4%B8%BA%E5%88%86%E5%80%BC%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E5%AD%98%E5%85%A5%20Sorted%20Set%E6%9C%89%E5%BA%8F%E9%9B%86%E5%90%88%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E8%BF%94%E5%9B%9E%E6%88%90%E5%8A%9F%E6%B7%BB%E5%8A%A0%E7%9A%84%E6%88%90%E5%91%98%E6%95%B0%E9%87%8F%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23f9f%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A%20%20%20%20style%20F%20fill%3A%239ff%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<hr><h2 id="geohash-算法原理" tabindex="-1">Geohash 算法原理 <a class="header-anchor" href="#geohash-算法原理" aria-label="Permalink to &quot;Geohash 算法原理&quot;">​</a></h2><p>Geohash 是一种将二维的经纬度坐标编码成一维字符串的算法，是 Redis GEO 实现地理位置功能的核心。</p><h3 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to &quot;核心思想&quot;">​</a></h3><ul><li>地球是一个三维球体，Geohash 先将其简化为二维平面，再把这个平面递归划分成一个个矩形网格</li><li>每个网格对应一个唯一的字符串编码，编码越长，网格越小，位置精度越高</li><li>两个位置的 Geohash 编码前缀越相似，说明它们的地理位置越近（这是 Redis 实现范围查找的关键）</li></ul><h3 id="编码过程" tabindex="-1">编码过程 <a class="header-anchor" href="#编码过程" aria-label="Permalink to &quot;编码过程&quot;">​</a></h3><p>以北京某点（经度 116.40，纬度 39.90）为例，编码步骤如下：</p><p><strong>步骤1</strong>：将经纬度归一化到 [-180, 180]（经度）、[-90, 90]（纬度）区间</p><ul><li>经度：116.40 ∈ [-180, 180]</li><li>纬度：39.90 ∈ [-90, 90]</li></ul><p><strong>步骤2</strong>：二分法编码（以纬度为例）</p><table tabindex="0"><thead><tr><th>区间</th><th>中点</th><th>39.90 落在左/右</th><th>编码位</th><th>新区间</th></tr></thead><tbody><tr><td>[-90, 90]</td><td>0</td><td>右（&gt;0）</td><td>1</td><td>[0, 90]</td></tr><tr><td>[0, 90]</td><td>45</td><td>左（&lt;45）</td><td>0</td><td>[0, 45]</td></tr><tr><td>[0, 45]</td><td>22.5</td><td>右（&gt;22.5）</td><td>1</td><td>[22.5, 45]</td></tr><tr><td>[22.5, 45]</td><td>33.75</td><td>右（&gt;33.75）</td><td>1</td><td>[33.75, 45]</td></tr><tr><td>[33.75, 45]</td><td>39.375</td><td>右（&gt;39.375）</td><td>1</td><td>[39.375, 45]</td></tr></tbody></table><p>最终纬度会得到一串二进制数（如 <code>10111...</code>），经度同理得到另一串二进制数（如 <code>11010...</code>）</p><p><strong>步骤3</strong>：合并经纬度二进制串</p><ul><li>规则：偶数位放经度，奇数位放纬度</li><li>示例：经度二进制 <code>11010</code>，纬度二进制 <code>10111</code>，合并后得到 <code>1 1 1 0 0 1 1 1 0 1</code></li></ul><p><strong>步骤4</strong>：将二进制串转成 Base32 编码</p><ul><li>Base32 编码表：0-9 + a-z（去掉 a,i,l,o），共32个字符，对应 5 位二进制数</li><li>把合并后的二进制串按 5 位一组拆分，每组转成一个 Base32 字符，最终得到 Geohash 字符串（如北京的 <code>wx4g0s83q90</code>）</li></ul><h3 id="geohash-关键特性" tabindex="-1">Geohash 关键特性 <a class="header-anchor" href="#geohash-关键特性" aria-label="Permalink to &quot;Geohash 关键特性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>降维</td><td>二维经纬度 → 一维字符串，便于存储和比较</td></tr><tr><td>精度可控</td><td>编码长度越长，精度越高（1位≈5000km，10位≈1.5m）</td></tr><tr><td>邻近性</td><td>编码前缀相同 → 位置相近（注意：相邻网格可能编码前缀不同，需特殊处理）</td></tr></tbody></table>',18)),(e(),E(d,null,{default:s(()=>[l(t,{id:"mermaid-396",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E8%BE%93%E5%85%A5%E7%BB%8F%E7%BA%AC%E5%BA%A6%3Cbr%2F%3E%EF%BC%88%E7%BB%8F%E5%BA%A6%EF%BC%9A116.40%EF%BC%8C%E7%BA%AC%E5%BA%A6%EF%BC%9A39.90%EF%BC%89%22%5D%20--%3E%20B%5B%22%E5%90%88%E6%B3%95%E6%80%A7%E6%A0%A1%E9%AA%8C%3Cbr%2F%3E%EF%BC%88%E7%BB%8F%E5%BA%A6%5B-180%2C180%5D%EF%BC%8C%E7%BA%AC%E5%BA%A6%5B-90%2C90%5D%EF%BC%89%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E4%BA%8C%E5%88%86%E6%B3%95%E7%BC%96%E7%A0%81%E7%BB%8F%E5%BA%A6%3Cbr%2F%3E%EF%BC%88%E9%80%92%E5%BD%92%E5%88%92%E5%88%86%E5%8C%BA%E9%97%B4%EF%BC%8C%E7%94%9F%E6%88%90%E4%BA%8C%E8%BF%9B%E5%88%B6%E4%B8%B2%EF%BC%89%22%5D%0A%20%20%20%20B%20--%3E%20D%5B%22%E4%BA%8C%E5%88%86%E6%B3%95%E7%BC%96%E7%A0%81%E7%BA%AC%E5%BA%A6%3Cbr%2F%3E%EF%BC%88%E9%80%92%E5%BD%92%E5%88%92%E5%88%86%E5%8C%BA%E9%97%B4%EF%BC%8C%E7%94%9F%E6%88%90%E4%BA%8C%E8%BF%9B%E5%88%B6%E4%B8%B2%EF%BC%89%22%5D%0A%20%20%20%20C%20%26%20D%20--%3E%20E%5B%22%E5%90%88%E5%B9%B6%E4%BA%8C%E8%BF%9B%E5%88%B6%E4%B8%B2%3Cbr%2F%3E%EF%BC%88%E5%81%B6%E6%95%B0%E4%BD%8D%E6%94%BE%E7%BB%8F%E5%BA%A6%EF%BC%8C%E5%A5%87%E6%95%B0%E4%BD%8D%E6%94%BE%E7%BA%AC%E5%BA%A6%EF%BC%89%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%E4%B8%B2%E8%BD%ACBase32%E7%BC%96%E7%A0%81%3Cbr%2F%3E%EF%BC%885%E4%BD%8D%E4%B8%80%E7%BB%84%EF%BC%8C%E6%98%A0%E5%B0%84%E4%B8%BA32%E4%B8%AA%E5%AD%97%E7%AC%A6%EF%BC%89%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E8%BE%93%E5%87%BAGeohash%E5%AD%97%E7%AC%A6%E4%B8%B2%3Cbr%2F%3E%EF%BC%88%E5%A6%82%EF%BC%9Awx4g0s83q90%EF%BC%89%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23f9f%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A%20%20%20%20style%20G%20fill%3A%239ff%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<hr><h2 id="redis-geo-实现机制" tabindex="-1">Redis GEO 实现机制 <a class="header-anchor" href="#redis-geo-实现机制" aria-label="Permalink to &quot;Redis GEO 实现机制&quot;">​</a></h2><p>Redis 并没有直接存储 Geohash 字符串作为有序集合的 score，而是将 Geohash 编码转换成 64位浮点数（score）存储在 Sorted Set 中。</p><h3 id="geoadd-存储位置" tabindex="-1">GEOADD 存储位置 <a class="header-anchor" href="#geoadd-存储位置" aria-label="Permalink to &quot;GEOADD 存储位置&quot;">​</a></h3><p>执行 <code>GEOADD key 经度 纬度 成员</code> 时，Redis 会：</p><ol><li>对传入的经纬度做合法性校验（经度 [-180,180]，纬度 [-90,90]）</li><li>将经纬度通过 Geohash 算法编码成 64 位的整数（作为有序集合的 <code>score</code>）</li><li>将成员作为有序集合的 <code>member</code>，<code>64位整数</code> 作为 <code>score</code>，存入指定的 key 中</li></ol><h3 id="geodist-计算距离-1" tabindex="-1">GEODIST 计算距离 <a class="header-anchor" href="#geodist-计算距离-1" aria-label="Permalink to &quot;GEODIST 计算距离&quot;">​</a></h3><p>Redis 计算距离并不是直接用 Geohash 编码，而是用经典的地理公式：<strong>Haversine 公式</strong>（计算球面上两点间的最短距离，即大圆距离）</p><p><strong>公式简化版</strong>： $$a = \\sin^2(\\Delta\\phi/2) + \\cos\\phi_1 \\cdot \\cos\\phi_2 \\cdot \\sin^2(\\Delta\\lambda/2)$$ $$c = 2 \\cdot \\arctan2(\\sqrt{a}, \\sqrt{1-a})$$ $$d = R \\cdot c$$</p><p>其中：</p><ul><li>$\\phi$ 是纬度（转弧度），$\\lambda$ 是经度（转弧度）</li><li>$\\Delta\\phi$ 是纬度差，$\\Delta\\lambda$ 是经度差</li><li>$R$ 是地球半径（约6371km）</li><li>$d$ 是最终距离</li></ul><p><strong>执行流程</strong>：</p><ol><li>通过 <code>GEOPOS</code> 获取两个成员的原始经纬度</li><li>将经纬度转成弧度，代入 Haversine 公式计算</li><li>根据指定单位（m/km/mi/ft）转换结果并返回</li></ol>',13)),(e(),E(d,null,{default:s(()=>[l(t,{id:"mermaid-481",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E8%BE%93%E5%85%A5%E4%B8%A4%E7%82%B9%E7%BB%8F%E7%BA%AC%E5%BA%A6%EF%BC%88%CF%861%2C%CE%BB1%EF%BC%89%EF%BC%88%CF%862%2C%CE%BB2%EF%BC%89%22%5D%20--%3E%20B%5B%22%E7%BB%8F%E7%BA%AC%E5%BA%A6%E8%BD%AC%E5%BC%A7%E5%BA%A6%3Cbr%2F%3E%EF%BC%88%E5%BC%A7%E5%BA%A6%3D%E8%A7%92%E5%BA%A6%C3%97%CF%80%2F180%EF%BC%89%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E8%AE%A1%E7%AE%97%E7%BA%AC%E5%BA%A6%E5%B7%AE%CE%94%CF%86%3D%CF%862-%CF%861%3Cbr%2F%3E%E7%BB%8F%E5%BA%A6%E5%B7%AE%CE%94%CE%BB%3D%CE%BB2-%CE%BB1%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E4%BB%A3%E5%85%A5Haversine%E5%85%AC%E5%BC%8F%EF%BC%9A%3Cbr%2F%3Ea%20%3D%20sin%C2%B2(%CE%94%CF%86%2F2)%20%2B%20cos%CF%861%C3%97cos%CF%862%C3%97sin%C2%B2(%CE%94%CE%BB%2F2)%3Cbr%2F%3Ec%20%3D%202%C3%97arctan2(%E2%88%9Aa%2C%20%E2%88%9A(1-a))%3Cbr%2F%3Ed%20%3D%20R%C3%97c%EF%BC%88R%3D%E5%9C%B0%E7%90%83%E5%8D%8A%E5%BE%846371km%EF%BC%89%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E8%BE%93%E5%87%BA%E4%B8%A4%E7%82%B9%E9%97%B4%E7%9B%B4%E7%BA%BF%E8%B7%9D%E7%A6%BB%22%5D%0A%0A%20%20%20%20style%20D%20fill%3A%23eee%2Cstroke%3A%23333%2Cstroke-width%3A1px%0A"})]),fallback:s(()=>[...a[2]||(a[2]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<h3 id="georadius-范围查找" tabindex="-1">GEORADIUS 范围查找 <a class="header-anchor" href="#georadius-范围查找" aria-label="Permalink to &quot;GEORADIUS 范围查找&quot;">​</a></h3><p><code>GEORADIUS</code> 和 <code>GEORADIUSBYMEMBER</code> 是 Redis GEO 最核心的范围查找功能，实现逻辑分两步：</p><p><strong>步骤1</strong>：Geohash 快速筛选（粗筛）</p><ul><li>以目标中心点（经纬度/指定成员的位置）为核心，计算出覆盖指定半径范围的所有 Geohash 网格（如半径10km，可能覆盖8个相邻的 Geohash 网格）</li><li>从有序集合中快速找出这些网格对应的所有成员（利用有序集合的范围查询特性，因为 Geohash 编码的 score 是有序的）</li></ul><p><strong>步骤2</strong>：Haversine 公式精准过滤（精筛）</p><ul><li>粗筛会得到候选成员列表（可能包含少量超出范围的成员）</li><li>对每个候选成员，用 Haversine 公式计算其与中心点的实际距离</li><li>过滤掉距离超过指定半径的成员，最终返回符合条件的结果</li></ul><h3 id="geopos-geohash-查询原始数据" tabindex="-1">GEOPOS/GEOHASH 查询原始数据 <a class="header-anchor" href="#geopos-geohash-查询原始数据" aria-label="Permalink to &quot;GEOPOS/GEOHASH 查询原始数据&quot;">​</a></h3><ul><li><code>GEOPOS</code>：从有序集合中取出成员对应的 score，反向解码成经纬度并返回</li><li><code>GEOHASH</code>：将 score 反向解码成 Geohash 字符串并返回</li></ul>',8)),(e(),E(d,null,{default:s(()=>[l(t,{id:"mermaid-538",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%E6%89%A7%E8%A1%8C%20GEORADIUS%20key%20%E7%BB%8F%E5%BA%A6%20%E7%BA%AC%E5%BA%A6%20%E5%8D%8A%E5%BE%84%20%E5%8D%95%E4%BD%8D%22%5D%20--%3E%20B%5B%22%E8%A7%A3%E6%9E%90%E4%B8%AD%E5%BF%83%E7%82%B9%E7%BB%8F%E7%BA%AC%E5%BA%A6%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E8%AE%A1%E7%AE%97%E8%A6%86%E7%9B%96%E8%8C%83%E5%9B%B4%E7%9A%84Geohash%E7%BD%91%E6%A0%BC%3Cbr%2F%3E%EF%BC%88%E7%B2%97%E7%AD%9B%EF%BC%9A%E7%A1%AE%E5%AE%9A%E5%80%99%E9%80%89%E7%BD%91%E6%A0%BC%EF%BC%89%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E4%BB%8ESorted%20Set%E4%B8%AD%E6%9F%A5%E8%AF%A2%3Cbr%2F%3E%E5%80%99%E9%80%89%E7%BD%91%E6%A0%BC%E5%AF%B9%E5%BA%94%E7%9A%84%E6%89%80%E6%9C%89%E6%88%90%E5%91%98%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E5%AF%B9%E6%AF%8F%E4%B8%AA%E5%80%99%E9%80%89%E6%88%90%E5%91%98%EF%BC%9A%3Cbr%2F%3E1.%20%E8%8E%B7%E5%8F%96%E5%8E%9F%E5%A7%8B%E7%BB%8F%E7%BA%AC%E5%BA%A6%3Cbr%2F%3E2.%20%E7%94%A8Haversine%E5%85%AC%E5%BC%8F%E8%AE%A1%E7%AE%97%E5%AE%9E%E9%99%85%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E8%BF%87%E6%BB%A4%E8%B6%85%E5%87%BA%E6%8C%87%E5%AE%9A%E5%8D%8A%E5%BE%84%E7%9A%84%E6%88%90%E5%91%98%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E6%8C%89%E8%B7%9D%E7%A6%BB%E6%8E%92%E5%BA%8F%EF%BC%88ASC%2FDESC%EF%BC%89%3Cbr%2F%3E%EF%BC%88%E5%8F%AF%E9%80%89%EF%BC%9A%E9%99%90%E5%88%B6%E8%BF%94%E5%9B%9E%E6%95%B0%E9%87%8FCOUNT%EF%BC%89%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%E8%BF%94%E5%9B%9E%E7%AC%A6%E5%90%88%E6%9D%A1%E4%BB%B6%E7%9A%84%E6%88%90%E5%91%98%E5%88%97%E8%A1%A8%3Cbr%2F%3E%EF%BC%88%E5%8F%AF%E9%80%89%EF%BC%9A%E5%B8%A6%E8%B7%9D%E7%A6%BBWITHDIST%2F%E7%BB%8F%E7%BA%AC%E5%BA%A6WITHCOORD%EF%BC%89%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23f9f%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A%20%20%20%20style%20H%20fill%3A%239ff%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A"})]),fallback:s(()=>[...a[3]||(a[3]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<hr><h2 id="实际应用场景" tabindex="-1">实际应用场景 <a class="header-anchor" href="#实际应用场景" aria-label="Permalink to &quot;实际应用场景&quot;">​</a></h2><h3 id="附近的人-商家" tabindex="-1">附近的人/商家 <a class="header-anchor" href="#附近的人-商家" aria-label="Permalink to &quot;附近的人/商家&quot;">​</a></h3><p>外卖APP的附近商家、社交APP的附近的人功能，通过 <code>GEORADIUS</code> 或 <code>GEORADIUSBYMEMBER</code> 快速查找指定范围内的目标</p><h3 id="地理位置围栏" tabindex="-1">地理位置围栏 <a class="header-anchor" href="#地理位置围栏" aria-label="Permalink to &quot;地理位置围栏&quot;">​</a></h3><p>物流系统监控车辆是否超出指定区域，通过定期检查车辆位置与围栏范围的关系实现</p><h3 id="距离计算" tabindex="-1">距离计算 <a class="header-anchor" href="#距离计算" aria-label="Permalink to &quot;距离计算&quot;">​</a></h3><p>打车APP计算用户到司机的距离，通过 <code>GEODIST</code> 命令快速获取两点间的直线距离</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li><strong>直线距离计算</strong>：Redis GEO 仅支持二维平面的直线距离计算，不考虑实际道路、地形等因素</li><li><strong>有序集合特性</strong>：底层是有序集合，因此可以用 <code>ZREM key 成员</code> 删除指定地理位置，用 <code>ZCARD key</code> 统计成员数量</li><li><strong>精度建议</strong>：Geohash 编码的精度有限，经纬度的精度建议保留 6 位小数（误差约 10 厘米）</li><li><strong>版本要求</strong>：Redis 3.2 及以上版本才支持 GEO 功能</li></ol><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Redis GEO 基于有序集合实现，核心是通过 Geohash 编码经纬度，支持地理位置的存储和计算。核心命令包括 <code>GEOADD</code>（添加）、<code>GEODIST</code>（计算距离）、<code>GEORADIUS/GEORADIUSBYMEMBER</code>（范围查找），主要用于附近的人/商家、距离计算等地理位置相关场景，需注意其仅计算直线距离的特性。</p><p>Geohash 是将二维经纬度编码成一维字符串的算法，核心是网格划分 + 二进制编码 + Base32 转换，前缀越相似的编码位置越近。Redis GEO 的 <code>GEODIST</code> 用 Haversine 公式计算球面距离，而非 Geohash；<code>GEORADIUS/GEORADIUSBYMEMBER</code> 先通过 Geohash 粗筛候选成员，再用 Haversine 公式精筛，兼顾性能和准确性。</p>',15))])}const u=h(n,[["render",A]]);export{D as __pageData,u as default};
